int startX, startY;
char startDir;

int dx[4] = {-1, 1, 0, 0}; // U, D, L, R
int dy[4] = {0, 0, -1, 1};
char dirChar[4] = {'U', 'D', 'L', 'R'};

// Convert direction character to index
int dirToIdx(char d) {
    switch(d) {
        case 'U': return 0;
        case 'D': return 1;
        case 'L': return 2;
        case 'R': return 3;
    }
    return -1;
}

// Check if position is inside grid and has a leaf
int isValid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] == '1';
}

// Find next valid position in given direction
int findNext(int x, int y, int dir, int *nx, int *ny) {
    *nx = x + dx[dir];
    *ny = y + dy[dir];
    while (isValid(*nx, *ny)) {
        return 1;
    }
    return 0;
}

// Perform DFS to find solution
int dfs(int x, int y, int dir, int remaining, char *path, int depth) {
    if (remaining == 1) {
        path[depth] = '\0';
        return 1;
    }

    // Try forward (same direction)
    int nx, ny;
    if (findNext(x, y, dir, &nx, &ny)) {
        grid[nx][ny] = '0'; // leaf sinks
        path[depth] = dirChar[dir];
        if (dfs(nx, ny, dir, remaining - 1, path, depth + 1))
            return 1;
        grid[nx][ny] = '1'; // backtrack
    }

    // Try left turn (dir - 1 mod 4)
    int leftDir = (dir + 3) % 4;
    if (findNext(x, y, leftDir, &nx, &ny)) {
        grid[nx][ny] = '0';
        path[depth] = dirChar[leftDir];
        if (dfs(nx, ny, leftDir, remaining - 1, path, depth + 1))
            return 1;
        grid[nx][ny] = '1';
    }

    // Try right turn (dir + 1 mod 4)
    int rightDir = (dir + 1) % 4;
    if (findNext(x, y, rightDir, &nx, &ny)) {
        grid[nx][ny] = '0';
        path[depth] = dirChar[rightDir];
        if (dfs(nx, ny, rightDir, remaining - 1, path, depth + 1))
            return 1;
        grid[nx][ny] = '1';
    }

    return 0;
}

