#define MAXN 10
char grid[MAXN][MAXN];
int N, M;
int total_leaves;
char path[1000];
int path_len;
int found;

// Directions: 0=U, 1=D, 2=L, 3=R
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};
char dname[] = "UDLR";

// For facing dir, get allowed jump directions (forward, left, right)
// Facing U(0): fwd=U(0), left=L(2), right=R(3)
// Facing D(1): fwd=D(1), left=R(3), right=L(2)
// Facing L(2): fwd=L(2), left=D(1), right=U(0)
// Facing R(3): fwd=R(3), left=U(0), right=D(1)
int allowed[4][3] = {{0,2,3},{1,3,2},{2,1,0},{3,0,1}};

void dfs(int r, int c, int facing, int leaves_remaining) {
    if (found) return;
    if (leaves_remaining == 1) {
        path[path_len] = 0;
        found = 1;
        return;
    }
    // Try all allowed directions and all distances
    for (int i = 0; i < 3; i++) {
        int d = allowed[facing][i];
        for (int dist = 1; dist < N+M; dist++) {
            int nr = r + dr[d]*dist;
            int nc = c + dc[d]*dist;
            if (nr < 0 || nr >= N || nc < 0 || nc >= M) break;
            if (grid[nr][nc] == '.' || grid[nr][nc] == 'S') {
                // Jump here
                char old = grid[r][c];
                grid[r][c] = '#'; // current leaf sinks
                char old_dest = grid[nr][nc];
                grid[nr][nc] = 'S'; // frog moves here
                path[path_len++] = dname[d];
                dfs(nr, nc, d, leaves_remaining - 1);
                if (found) return;
                path_len--;
                grid[r][c] = old;
                grid[nr][nc] = old_dest;
            }
        }
    }
}

