            char ch = a[i][j];
            if (ch == '.' ) continue;
            total++;
            if (ch == 'U' || ch == 'D' || ch == 'L' || ch == 'R') {
                sr = i;
                sc = j;
                dir = ch;
                a[i][j] = '*'; /* treat start as a leaf */
            }
        }
    }

    /* Collect all leaves in snake order */
    Cell *ord = (Cell *)malloc(total * sizeof(Cell));
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '*') {
                    ord[k].r = i;
                    ord[k].c = j;
                    k++;
                }
            }
        } else {
            for (int j = m - 1; j >= 0; j--) {
                if (a[i][j] == '*') {
                    ord[k].r = i;
                    ord[k].c = j;
                    k++;
                }
            }
        }
    }

    /* Find start position in this order */
    int pos = 0;
    for (int i = 0; i < total; i++) {
        if (ord[i].r == sr && ord[i].c == sc) {
            pos = i;
            break;
        }
    }

    /* We output a path visiting all leaves exactly once in the snake order,
       rotated so it starts from the frog's starting leaf. */
    char *ans = (char *)malloc((total + 5) * sizeof(char));
    int len = 0;

    for (int step = 1; step < total; step++) {
        Cell cur = ord[(pos + step - 1) % total];
        Cell nxt = ord[(pos + step) % total];

        if (nxt.r == cur.r) {
            if (nxt.c == cur.c + 1) ans[len++] = 'R';
            else if (nxt.c == cur.c - 1) ans[len++] = 'L';
        } else if (nxt.c == cur.c) {
            if (nxt.r == cur.r + 1) ans[len++] = 'D';
            else if (nxt.r == cur.r - 1) ans[len++] = 'U';
        } else {
            /* If the input is guaranteed solvable, this should not happen. */
            /* Fallback: no solution format specified, so stop. */
            break;
        }
    }
    ans[len] = '\0';

    printf("%s\n", ans);

    for (int i = 0; i < n; i++) free(a[i]);
    free(a);
    free(ord);
    free(ans);
    return 0;
}

