                grid[i][j] = 'o'; // treat as leaf
            }
        }
    }

    // Count leaves
    int leafCount = 0;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            if (grid[i][j] == 'o') leafCount++;

