        bool moved = false;
        // Try forward
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (isValid(nx, ny)) {
            grid[x][y] = '.'; // sink current leaf
            leafCount--;
            x = nx; y = ny;
            ans += dirChar[dir];
            moved = true;
        } else {
            // Try left (dir-1 mod 4)
            int leftDir = (dir + 3) % 4;
            nx = x + dx[leftDir];
            ny = y + dy[leftDir];
            if (isValid(nx, ny)) {
                grid[x][y] = '.';
                leafCount--;
                x = nx; y = ny;
                dir = leftDir;
                ans += dirChar[dir];
                moved = true;
            } else {
                // Try right (dir+1 mod 4)
                int rightDir = (dir + 1) % 4;
                nx = x + dx[rightDir];
                ny = y + dy[rightDir];
                if (isValid(nx, ny)) {
                    grid[x][y] = '.';
                    leafCount--;
                    x = nx; y = ny;
                    dir = rightDir;
                    ans += dirChar[dir];
                    moved = true;
                }
            }
        }
        if (!moved) break; // no move possible
    }

    cout << ans << "\n";

    return 0;
