    if (remaining == 1) return true;

    // Try forward, left, right directions
    int dirs[3] = {dir, leftOf[dir], rightOf[dir]};

    for (int di = 0; di < 3; di++) {
        int nd = dirs[di];
        // Jump any distance in direction nd
        int nr = r + dr[nd];
        int nc = c + dc[nd];
        while (nr >= 0 && nr < R && nc >= 0 && nc < C) {
            if (present[nr][nc]) {
                // Jump here
                present[r][c] = false; // current leaf sinks
                path += dirChar[nd];
                if (dfs(nr, nc, nd, remaining - 1)) return true;
                path.pop_back();
                present[r][c] = true;
            }
            nr += dr[nd];
            nc += dc[nd];
        }
    }
    return false;
}

