#include <bits/stdc++.h>
using namespace std;

/*
We need output any sequence of jumps that visits all lotus leaves exactly once
(starting leaf included), with movement allowed each step to one of the 3
directions relative to current facing: forward / left / right (never backward).
After moving, facing becomes the move direction.

A standard constructive solution:
Use a snake traversal of all cells. For a full rectangle, consecutive moves are
between orthogonally adjacent cells. We only need ensure no move is a direct
backward turn relative to previous move. In a usual snake order, this never
happens: moves are repetitions within a row and single vertical transitions
between row ends.

We can choose one of 8 snake patterns (row-wise or column-wise, each from one
of four corners) and one of the 4 possible initial facings. We simulate and
pick any pattern where the first move is not backward relative to initial
facing, and all subsequent moves are not backward relative to previous move.
Since subsequent snake moves already satisfy this, only the first move matters,
but we just check all.

Input format assumed:
n m
x y
dir
where dir is one of U,D,L,R
Coordinates are 1-based.

We output the sequence of move directions as characters, length n*m-1.

This is the known construction for the "frog on leaves" style task on a full
n x m grid.
*/

struct Pos {
    int r, c;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    int sx, sy;
    cin >> sx >> sy;
    char sd;
    cin >> sd;

    auto dirId = [&](char ch) -> int {
        if (ch == 'U') return 0;
        if (ch == 'R') return 1;
        if (ch == 'D') return 2;
        return 3; // L
    };

    auto stepDir = [&](Pos a, Pos b) -> char {
        if (b.r == a.r - 1) return 'U';
        if (b.r == a.r + 1) return 'D';
        if (b.c == a.c - 1) return 'L';
        return 'R';
    };

    auto opposite = [&](char ch) -> char {
        if (ch == 'U') return 'D';
        if (ch == 'D') return 'U';
        if (ch == 'L') return 'R';
        return 'L';
    };

    vector<vector<Pos>> patterns;

    // Row-wise snakes from four corners
    for (int startTop = 0; startTop < 2; ++startTop) {
        for (int startLeft = 0; startLeft < 2; ++startLeft) {
            vector<Pos> ord;
            vector<int> rows, cols;
            if (startTop) for (int i = 1; i <= n; ++i) rows.push_back(i);
            else for (int i = n; i >= 1; --i) rows.push_back(i);

            bool leftToRight = startLeft;
            for (int rr = 0; rr < (int)rows.size(); ++rr) {
                int i = rows[rr];
                if (leftToRight) {
                    for (int j = 1; j <= m; ++j) ord.push_back({i, j});
                } else {
                    for (int j = m; j >= 1; --j) ord.push_back({i, j});
                }
                leftToRight = !leftToRight;
            }
            patterns.push_back(ord);
        }
    }

    // Column-wise snakes from four corners
    for (int startLeft = 0; startLeft < 2; ++startLeft) {
        for (int startTop = 0; startTop < 2; ++startTop) {
            vector<Pos> ord;
            vector<int> cols, rows;
            if (startLeft) for (int j = 1; j <= m; ++j) cols.push_back(j);
            else for (int j = m; j >= 1; --j) cols.push_back(j);

            bool topToBottom = startTop;
            for (int cc = 0; cc < (int)cols.size(); ++cc) {
                int j = cols[cc];
                if (topToBottom) {
                    for (int i = 1; i <= n; ++i) ord.push_back({i, j});
                } else {
                    for (int i = n; i >= 1; --i) ord.push_back({i, j});
                }
                topToBottom = !topToBottom;
            }
            patterns.push_back(ord);
        }
    }

    for (auto &ord : patterns) {
        if (!(ord[0].r == sx && ord[0].c == sy)) continue;

        bool ok = true;
        string ans;
        char facing = sd;
        for (int i = 1; i < (int)ord.size(); ++i) {
            char mv = stepDir(ord[i - 1], ord[i]);
            if (mv == opposite(facing)) {
                ok = false;
                break;
            }
            ans.push_back(mv);
            facing = mv;
        }
        if (ok) {
            cout << ans << '\n';
            return 0;
        }
    }

    // If no pattern starts at the given cell, impossible under this assumed model.
    // Problem statements of this type guarantee existence.
    return 0;
}

