public class FrogLeap {
    static int n, m;
    static char[][] grid;
    static int startX, startY;
    static char startDir;
    static int leaves;

    // Directions: 0=up,1=right,2=down,3=left
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, 1, 0, -1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        sc.nextLine();
        grid = new char[n][m];
        leaves = 0;
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'F') {
                    startX = i;
                    startY = j;
                    leaves++;
                } else if (grid[i][j] == 'L') {
                    leaves++;
                }
            }
        }
        startDir = sc.next().charAt(0);
        sc.close();

        // Convert direction to index
        int dirIdx = 0;
        if (startDir == 'U') dirIdx = 0;
        else if (startDir == 'R') dirIdx = 1;
        else if (startDir == 'D') dirIdx = 2;
        else if (startDir == 'L') dirIdx = 3;

        StringBuilder path = new StringBuilder();
        solve(startX, startY, dirIdx, leaves, path);
        System.out.println(path.toString());
    }

    static boolean solve(int x, int y, int dir, int remaining, StringBuilder path) {
        if (remaining == 1) {
            return true;
        }

        // Try forward first, then left, then right
        int[] order = {0, -1, 1}; // forward, left, right relative to current direction
        for (int rel : order) {
            int newDir = (dir + rel + 4) % 4;
            int nx = x + dx[newDir];
            int ny = y + dy[newDir];

            if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 'L') {
                // Jump to this leaf
                grid[nx][ny] = 'F';
                grid[x][y] = '.';
                char move = 0;
                if (newDir == 0) move = 'U';
                else if (newDir == 1) move = 'R';
                else if (newDir == 2) move = 'D';
                else if (newDir == 3) move = 'L';
                path.append(move);

                if (solve(nx, ny, newDir, remaining - 1, path)) {
                    return true;
                }

                // Backtrack
                path.deleteCharAt(path.length() - 1);
                grid[nx][ny] = 'L';
                grid[x][y] = 'F';
            }
        }
        return false;
    }
}

