public class Main {
    static int R, C;
    static boolean[][] grid;
    static int totalLeaves;
    static int[] dr = {-1, 1, 0, 0}; // U, D, L, R
    static int[] dc = {0, 0, -1, 1};
    static char[] dirChar = {'U', 'D', 'L', 'R'};
    static List<Character> result = new ArrayList<>();

    // Relative turns: given facing dir, left/right/forward indices
    // For direction d: forward=d, left=turn left, right=turn right
    // U(0)->left=L(2), right=R(3)
    // D(1)->left=R(3), right=L(2)
    // L(2)->left=D(1), right=U(0)
    // R(3)->left=U(0), right=D(1)
    static int[] leftOf =  {2, 3, 1, 0};
    static int[] rightOf = {3, 2, 0, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        R = sc.nextInt(); C = sc.nextInt();
        int sr = sc.nextInt(); int scc = sc.nextInt();
        String dirS = sc.next();
        int startDir = "UDLR".indexOf(dirS.charAt(0));
        grid = new boolean[R][C];
        totalLeaves = 0;
        for (int i = 0; i < R; i++) {
            String line = sc.next();
            for (int j = 0; j < C; j++) {
                if (line.charAt(j) == 'L') { grid[i][j] = true; totalLeaves++; }
            }
        }
        grid[sr][scc] = false; // frog is on this leaf, it will sink when frog leaves
        // Actually frog starts here, count it as visited
        dfs(sr, scc, startDir, 1);
        for (char ch : result) System.out.print(ch);
        System.out.println();
    }

    static boolean dfs(int r, int c, int dir, int visited) {
        if (visited == totalLeaves) return true;
        int[] moves = {dir, leftOf[dir], rightOf[dir]};
        for (int nd : moves) {
            int nr = r + dr[nd];
            int nc = c + dc[nd];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc]) {
                grid[nr][nc] = false;
                result.add(dirChar[nd]);
                if (dfs(nr, nc, nd, visited + 1)) return true;
                result.remove(result.size() - 1);
                grid[nr][nc] = true;
            }
        }
        return false;
    }
}

