/*
We are given a rectangular grid containing lotus leaves.
One cell contains the frog with an initial facing direction among U,D,L,R.
All non-empty cells are leaves. Whenever the frog jumps onto another leaf,
the previous leaf sinks, so the frog may visit each leaf at most once.
We need to output a sequence of absolute jump directions (U,D,L,R) so that
the frog visits all leaves exactly once, ending with only one leaf remaining.

Allowed move rule:
If current facing is F, next jump may be:
- forward
- left relative to F
- right relative to F
but not backward.
After jumping, facing becomes the jump direction.

Observation:
This is exactly finding a Hamiltonian path over all leaf cells, starting from
the frog start cell, with an additional constraint on consecutive move directions:
for two consecutive absolute directions d1 then d2, d2 cannot be opposite of d1.
(First move also cannot be opposite to initial facing.)

A full general Hamiltonian-path problem is hard, but these contest tasks usually
use small enough number of leaves. We solve with DFS + memoization over subsets.

State:
(mask, last, dir)
- visited set mask
- current position index last
- current facing dir (0..3)

Transition:
move to any unvisited leaf in one of the 4 cardinal directions, provided:
1) destination leaf exists
2) absolute direction nd is not opposite of current dir
3) nd is reachable by a straight jump in that direction over water only
   (all intermediate cells empty; only destination is a leaf)

This matches "jumping between leaves" on the pond.

We precompute for each leaf and each direction the nearest leaf visible in that
direction with only empty cells between them; if blocked by another leaf first,
that one is the only possible landing spot.

If a solution exists, reconstruct and print sequence.
*/

public class Main {
    static final int U = 0, R = 1, D = 2, L = 3;
    static final int[] DR = {-1, 0, 1, 0};
    static final int[] DC = {0, 1, 0, -1};
    static final char[] DCH = {'U', 'R', 'D', 'L'};

    static int H, W;
    static char[][] g;

    static List<int[]> leaves = new ArrayList<>();
    static int[][] id;
    static int n;
    static int start = -1;
    static int startDir;

    static int[][] nextLeaf; // [leaf][dir] -> destination leaf id or -1

    static HashMap<Long, Boolean> memo = new HashMap<>();
    static HashMap<Long, Integer> choice = new HashMap<>();

    static int dirFromChar(char ch) {
        if (ch == 'U' || ch == '^') return U;
        if (ch == 'R' || ch == '>') return R;
        if (ch == 'D' || ch == 'V' || ch == 'v') return D;
        return L; // 'L' or '<'
    }

    static boolean isStartChar(char ch) {
        return ch == 'U' || ch == 'D' || ch == 'L' || ch == 'R' ||
               ch == '^' || ch == 'v' || ch == 'V' || ch == '<' || ch == '>';
    }

    static boolean isLeafChar(char ch) {
        return ch != '.';
    }

    static boolean opposite(int a, int b) {
        return ((a + 2) & 3) == b;
    }

    static long key(long mask, int last, int dir) {
        return (mask << 8) ^ ((long) last << 2) ^ dir;
    }

    static boolean dfs(long mask, int last, int dir) {
        if (Long.bitCount(mask) == n) return true;
        long k = key(mask, last, dir);
        Boolean got = memo.get(k);
        if (got != null) return got;

        // heuristic: try directions in order forward, left, right, backward(last impossible by rule)
        int[] order = {dir, (dir + 3) & 3, (dir + 1) & 3, (dir + 2) & 3};
        for (int nd : order) {
            if (opposite(dir, nd)) continue;
            int to = nextLeaf[last][nd];
            if (to == -1) continue;
            if (((mask >> to) & 1L) != 0) continue;
            if (dfs(mask | (1L << to), to, nd)) {
                memo.put(k, true);
                choice.put(k, nd);
                return true;
            }
        }

        memo.put(k, false);
        return false;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(first);
        H = Integer.parseInt(st.nextToken());
        W = Integer.parseInt(st.nextToken());

        g = new char[H][W];
        id = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(id[i], -1);

        for (int i = 0; i < H; i++) {
            String s = br.readLine();
            while (s != null && s.length() < W) {
                String t = br.readLine();
                if (t == null) break;
                s += t;
            }
            for (int j = 0; j < W; j++) {
                char ch = s.charAt(j);
                g[i][j] = ch;
                if (isLeafChar(ch)) {
                    id[i][j] = leaves.size();
                    leaves.add(new int[]{i, j});
                }
            }
        }

        n = leaves.size();
        for (int idx = 0; idx < n; idx++) {
            int r = leaves.get(idx)[0], c = leaves.get(idx)[1];
            char ch = g[r][c];
            if (isStartChar(ch)) {
                start = idx;
                startDir = dirFromChar(ch);
            }
        }

        if (start == -1) {
            // Fallback: if no explicit start char, assume first leaf and facing up.
            start = 0;
            startDir = U;
        }

        nextLeaf = new int[n][4];
        for (int i = 0; i < n; i++) Arrays.fill(nextLeaf[i], -1);

        for (int idx = 0; idx < n; idx++) {
            int r = leaves.get(idx)[0], c = leaves.get(idx)[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d], nc = c + DC[d];
                while (0 <= nr && nr < H && 0 <= nc && nc < W) {
                    if (id[nr][nc] != -1) {
                        nextLeaf[idx][d] = id[nr][nc];
                        break;
                    }
                    nr += DR[d];
                    nc += DC[d];
                }
            }
        }

        long initMask = 1L << start;
        boolean ok = dfs(initMask, start, startDir);

        if (!ok) {
            // If no solution, print nothing or impossible.
            // Problem statements of this type usually guarantee existence.
            System.out.println("IMPOSSIBLE");
            return;
        }

        StringBuilder ans = new StringBuilder();
        long mask = initMask;
        int last = start, dir = startDir;
        while (Long.bitCount(mask) < n) {
            long k = key(mask, last, dir);
            int nd = choice.get(k);
            ans.append(DCH[nd]);
            int to = nextLeaf[last][nd];
            mask |= 1L << to;
            last = to;
            dir = nd;
        }

        System.out.println(ans.toString());
    }
}

import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    # Expected input:
    # n m
    # n lines of grid
    #
    # Grid symbols:
    # . = no leaf
    # * = leaf
    # U/D/L/R = starting leaf and initial facing direction
    #
    # We output a sequence of absolute moves U/D/L/R such that the frog visits
    # every leaf exactly once (the previous one sinks), ending with one leaf left.
    #
    # Strategy:
    # Build a Hamiltonian path over all existing leaves in the induced grid graph,
    # starting from the given start cell. Consecutive moves must never be the
    # backward direction relative to current facing, i.e. each turn is straight/left/right.
    # Since facing becomes the move direction, this means for consecutive moves
    # dir[i-1] -> dir[i], dir[i] must not be opposite of dir[i-1].
    #
    # We use DFS with pruning to find such a path.

    n, m = map(int, data[0].split())
    grid = [list(row.rstrip('\n')) for row in data[1:1+n]]

    dirs = [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]
    ch_to_dir = {'U':0, 'D':1, 'L':2, 'R':3}
    opposite = {0:1, 1:0, 2:3, 3:2}

    leaves = []
    start = None
    start_dir = None

    for i in range(n):
        for j in range(m):
            c = grid[i][j]
            if c == '*':
                leaves.append((i, j))
            elif c in ch_to_dir:
                leaves.append((i, j))
                start = (i, j)
                start_dir = ch_to_dir[c]

    leaf_set = set(leaves)
    total = len(leaves)

    if total <= 1:
        print()
        return

    idx = {p:k for k, p in enumerate(leaves)}
    adj = [[] for _ in range(total)]
    move_char = {}

    for k, (x, y) in enumerate(leaves):
        for d, (dx, dy, ch) in enumerate(dirs):
            nx, ny = x + dx, y + dy
            if (nx, ny) in leaf_set:
                adj[k].append((idx[(nx, ny)], d))
                move_char[(k, idx[(nx, ny)])] = ch

    start_idx = idx[start]

    visited = [False] * total
    path_moves = []
    sys.setrecursionlimit(1_000_000)

    # Connectivity pruning on remaining unvisited vertices plus current vertex.
    def connected_remaining(cur):
        allowed = [i for i in range(total) if (not visited[i]) or i == cur]
        if not allowed:
            return True
        allowed_set = set(allowed)
        stack = [cur]
        seen = {cur}
        while stack:
            u = stack.pop()
            for v, _ in adj[u]:
                if v in allowed_set and v not in seen:
                    seen.add(v)
                    stack.append(v)
        return len(seen) == len(allowed_set)

    # Degree pruning: for a Hamiltonian path extension from current endpoint,
    # among remaining graph (unvisited + current), no vertex except possibly current
    # may have degree 0; and at most one other vertex may have degree 1.
    def degree_prune(cur):
        allowed = [i for i in range(total) if (not visited[i]) or i == cur]
        allowed_set = set(allowed)
        ones = 0
        for u in allowed:
            deg = 0
            for v, _ in adj[u]:
                if v in allowed_set:
                    deg += 1
            if u == cur:
                if deg == 0 and len(allowed) > 1:
                    return False
            else:
                if deg == 0:
                    return False
                if deg == 1:
                    ones += 1
                    if ones > 1:
                        return False
        return True

    def dfs(u, facing, cnt):
        if cnt == total:
            return True

        # Candidate moves: cannot go backward relative to current facing.
        cand = []
        for v, d in adj[u]:
            if visited[v]:
                continue
            if d == opposite[facing]:
                continue
            # heuristic: smaller onward degree first
            onward = 0
            for w, d2 in adj[v]:
                if not visited[w] and w != u and d2 != opposite[d]:
                    onward += 1
            cand.append((onward, v, d))

        cand.sort()

        for _, v, d in cand:
            visited[v] = True
            path_moves.append(dirs[d][2])

            ok = True
            if cnt + 1 < total:
                if not connected_remaining(v):
                    ok = False
                elif not degree_prune(v):
                    ok = False

            if ok and dfs(v, d, cnt + 1):
                return True

            path_moves.pop()
            visited[v] = False

        return False

    visited[start_idx] = True
    if dfs(start_idx, start_dir, 1):
        print(''.join(path_moves))
    else:
        # Problem statement guarantees a solution in intended tests.
        # If not found, output nothing.
        print()

if __name__ == "__main__":
    solve()
